  `token_estimate` int unsigned NOT NULL DEFAULT '0',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SUCCESS',
  `metadata` json DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ai_generation_logs_user_id_foreign` (`user_id`),
  KEY `ai_generation_logs_created_at_task_type_index` (`created_at`,`task_type`),
  KEY `ai_generation_logs_task_type_index` (`task_type`)
