INSERT INTO `backup_old_lms_assignments` VALUES (1,1,1,'Tugas Mandiri 1: Pemecahan Masalah Polinomial Terapan','Kerjakan soal studi kasus polinomial berikut pada buku catatan matematika Anda atau buat file dokumen PDF:\n\n1. Tentukan hasil bagi dan sisa pembagian f(x) = 2x^4 - 3x^3 + 5x - 2 oleh (x - 2) menggunakan metode Horner.\n2. Tentukan nilai k jika (x + 1) merupakan faktor dari g(x) = x^3 + kx^2 - 4x - 12.\n\nUpload hasil pekerjaan dalam format PDF atau foto yang jelas sebelum batas waktu berakhir.','formatif',100,75,'2026-10-25 23:59:00',1,NULL,1,'2026-10-20 12:47:24','2026-10-20 12:47:24');
