INSERT INTO `backup_old_lms_quiz_questions` VALUES (1,1,'Berapakah sisa pembagian dari polinomial P(x) = x^3 - 4x^2 + 6x - 2 jika dibagi oleh (x - 1)?','multiple_choice','[{\"key\": \"A\", \"text\": \"1\"}, {\"key\": \"B\", \"text\": \"2\"}, {\"key\": \"C\", \"text\": \"3\"}, {\"key\": \"D\", \"text\": \"4\"}, {\"key\": \"E\", \"text\": \"5\"}]','A','Sisa pembagian P(1) = 1^3 - 4(1)^2 + 6(1) - 2 = 1 - 4 + 6 - 2 = 1.',50.00,1,'2026-10-20 12:47:24','2026-10-20 12:47:24'),(2,1,'Derajat dari polinomial f(x) = (2x^2 - 3)(x^3 + 5x - 1) adalah 5.','true_false','[{\"key\": \"BENAR\", \"text\": \"Benar\"}, {\"key\": \"SALAH\", \"text\": \"Salah\"}]','BENAR','Perkalian suku derajat tertinggi adalah 2x^2 * x^3 = 2x^5, sehingga berderajat 5.',50.00,2,'2026-10-20 12:47:24','2026-10-20 12:47:24');
