INSERT INTO `backup_old_lms_topics` VALUES (1,1,'Modul 1: Fungsi Polinomial dan Teorema Sisa','Peserta didik dapat menentukan operasi hitung pada polinomial, faktorisasi, dan menyelesaikan masalah kontekstual yang melibatkan sistem polinomial.','1. Memahami konsep derajat dan koefisien polinomial. 2. Menerapkan pembagian bersusun dan metode Horner. 3. Menganalisis nilai sisa dan akar polinomial.','[\"Bernalar Kritis\", \"Mandiri\", \"Kreatif\"]',1,1,'2026-10-20 12:46:51','2026-10-20 12:46:51'),(2,1,'Modul 2: Eksponen, Logaritma & Pemodelan Finansial','Peserta didik mampu memodelkan fenomena eksponensial (pertumbuhan dan peluruhan) dalam kehidupan nyata.','1. Menemukan sifat-sifat eksponen. 2. Memodelkan bunga majemuk dan peluruhan zat radioaktif.','[\"Bernalar Kritis\", \"Gotong Royong\"]',2,1,'2026-10-20 12:46:51','2026-10-20 12:46:51');
