DROP TABLE IF EXISTS `bk_psychological_test_questions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bk_psychological_test_questions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `test_id` bigint unsigned NOT NULL,
  `question_number` int NOT NULL,
  `question_text` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `dimension` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `dimension_name` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `scale_type` enum('LIKERT_4','LIKERT_5','CHOICE') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'LIKERT_4',
  `options` json DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `bk_psychological_test_questions_test_id_question_number_index` (`test_id`,`question_number`),
  CONSTRAINT `bk_psychological_test_questions_test_id_foreign` FOREIGN KEY (`test_id`) REFERENCES `bk_psychological_tests` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=93 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

