INSERT INTO `bk_psychological_tests` VALUES (1,'vak','Tes Gaya Belajar VAK (Visual, Auditori, Kinestetik)','GAYA_BELAJAR','Asesmen preferensi modalitas sensorik siswa dalam menyerap, mengolah, dan mengingat informasi materi pelajaran.','Pilihlah salah satu jawaban yang paling menggambarkan kebiasaan belajarmu sehari-hari (1 = Sangat Tidak Sesuai, 2 = Kurang Sesuai, 3 = Sesuai, 4 = Sangat Sesuai). Tidak ada jawaban benar atau salah.',20,24,1,'2026-11-04 03:17:21','2026-11-04 03:17:21'),(2,'riasec','Tes Minat Bakat Karier Holland RIASEC','MINAT_BAKAT','Asesmen minat vokasional dan kepribadian karier berdasarkan teori John Holland untuk rekomendasi jurusan kuliah dan profesi masa depan.','Nyatakan seberapa besar ketertarikan atau kesesuaian dirimu terhadap aktivitas-aktivitas berikut (1 = Sangat Tidak Tertarik, 2 = Kurang Tertarik, 3 = Tertarik, 4 = Sangat Tertarik).',25,36,1,'2026-11-04 03:17:21','2026-11-04 03:17:21'),(3,'gardner','Tes Kecerdasan Majemuk (Howard Gardner Multiple Intelligences)','KECERDASAN_MAJEMUK','Pemetaan 8 profil kecerdasan majemuk siswa untuk mengoptimalkan potensi belajar dan pengembangan diri holistik.','Pilihlah tingkat kecocokan setiap pernyataan dengan potensi dirimu (1 = Tidak Sesuai, 2 = Kadang-kadang, 3 = Sering, 4 = Sangat Menonjol).',25,32,1,'2026-11-04 03:17:22','2026-11-04 03:17:22');
