DROP TABLE IF EXISTS `library_books`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `library_books` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `book_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `book_type` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'fisik',
  `is_digital_flip` tinyint(1) NOT NULL DEFAULT '0',
  `digital_file_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `digital_content` longtext COLLATE utf8mb4_unicode_ci,
  `slug` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `author` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `publisher` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `publish_year` smallint unsigned DEFAULT NULL,
  `isbn` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `call_number` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `category_id` bigint unsigned DEFAULT NULL,
  `ddc_code` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `category_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Umum',
  `collection_type` enum('physical','digital','both') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'both',
  `total_copies` int unsigned NOT NULL DEFAULT '1',
  `available_copies` int unsigned NOT NULL DEFAULT '1',
  `location_shelf` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `rack_location` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cover_image` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `file_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_ebook` tinyint(1) NOT NULL DEFAULT '0',
  `ebook_file` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ebook_pages` longtext COLLATE utf8mb4_unicode_ci,
  `synopsis` text COLLATE utf8mb4_unicode_ci,
  `description` text COLLATE utf8mb4_unicode_ci,
  `page_count` int unsigned NOT NULL DEFAULT '0',
  `pages_count` int NOT NULL DEFAULT '0',
  `language` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Indonesia',
  `curriculum` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Kurikulum Merdeka',
  `grade_level` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `views_count` int unsigned NOT NULL DEFAULT '0',
  `reads_count` int unsigned NOT NULL DEFAULT '0',
  `loans_count` int NOT NULL DEFAULT '0',
  `borrow_count` int unsigned NOT NULL DEFAULT '0',
  `is_featured` tinyint(1) NOT NULL DEFAULT '0',
  `is_available` tinyint(1) NOT NULL DEFAULT '1',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `library_books_slug_unique` (`slug`),
  KEY `library_books_category_id_foreign` (`category_id`),
  KEY `library_books_isbn_index` (`isbn`),
  KEY `library_books_call_number_index` (`call_number`),
  KEY `library_books_ddc_code_index` (`ddc_code`),
  KEY `library_books_collection_type_index` (`collection_type`),
  KEY `library_books_is_featured_index` (`is_featured`),
  KEY `library_books_is_available_index` (`is_available`),
  CONSTRAINT `library_books_category_id_foreign` FOREIGN KEY (`category_id`) REFERENCES `library_categories` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
