DROP TABLE IF EXISTS `library_loans`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `library_loans` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `loan_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `book_id` bigint unsigned NOT NULL,
  `user_id` bigint unsigned NOT NULL,
  `request_date` datetime DEFAULT NULL,
  `member_id` bigint unsigned DEFAULT NULL,
  `borrower_type` enum('student','teacher','staff') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'student',
  `borrower_name` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `borrower_identifier` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `borrower_class_or_dept` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `loan_date` date NOT NULL,
  `due_date` date NOT NULL,
  `pickup_deadline` date DEFAULT NULL,
  `return_date` date DEFAULT NULL,
  `status` enum('pending','approved','borrowed','returned','rejected','overdue') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `fine_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `is_fine_paid` tinyint(1) NOT NULL DEFAULT '0',
  `extension_count` tinyint unsigned NOT NULL DEFAULT '0',
  `fines_amount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `approved_by` bigint unsigned DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `rejection_reason` text COLLATE utf8mb4_unicode_ci,
  `request_notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `library_loans_loan_code_unique` (`loan_code`),
  KEY `library_loans_book_id_foreign` (`book_id`),
  KEY `library_loans_user_id_foreign` (`user_id`),
  KEY `library_loans_approved_by_foreign` (`approved_by`),
  KEY `library_loans_borrower_type_index` (`borrower_type`),
  KEY `library_loans_borrower_identifier_index` (`borrower_identifier`),
  KEY `library_loans_status_index` (`status`),
  CONSTRAINT `library_loans_approved_by_foreign` FOREIGN KEY (`approved_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `library_loans_book_id_foreign` FOREIGN KEY (`book_id`) REFERENCES `library_books` (`id`) ON DELETE CASCADE,
  CONSTRAINT `library_loans_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
