INSERT INTO `school_bells` VALUES (1,'Murottal Al-Qur\'an Pra KBM (Pagi Hari)','06:45','[\"Senin\", \"Selasa\", \"Rabu\", \"Kamis\", \"Jumat\"]','murottal','https://cdn.islamic.network/quran/audio-surah/128/ar.alafasy/55.mp3',55,'Ar-Rahman',85,900,'Murottal Al-Qur\'an menyambut kedatangan peserta didik dan guru sebelum KBM dimulai',NULL,1,1,'2026-11-10 11:51:58','2026-11-10 13:44:02'),(2,'Bel Masuk Kelas & KBM Jam Ke-1','07:00','[\"Senin\", \"Selasa\", \"Rabu\", \"Kamis\", \"Jumat\"]','chime',NULL,NULL,NULL,100,15,'Tanda masuk kelas, seluruh siswa dan guru bersiap di ruang kelas','Perhatian, saatnya jam pelajaran pertama dimulai. Selamat belajar.',1,2,'2026-11-10 11:51:58','2026-11-10 11:51:58'),(3,'Ganti Jam Pelajaran Ke-2','07:45','[\"Senin\", \"Selasa\", \"Rabu\", \"Kamis\", \"Jumat\"]','chime',NULL,NULL,NULL,95,10,'Pergantian mata pelajaran jam ke-2','Saatnya pergantian jam pelajaran ke-2.',1,3,'2026-11-10 11:51:58','2026-11-10 11:51:58'),(4,'Ganti Jam Pelajaran Ke-3','08:30','[\"Senin\", \"Selasa\", \"Rabu\", \"Kamis\", \"Jumat\"]','chime',NULL,NULL,NULL,95,10,'Pergantian mata pelajaran jam ke-3','Saatnya pergantian jam pelajaran ke-3.',1,4,'2026-11-10 11:51:58','2026-11-10 11:51:58'),(5,'Ganti Jam Pelajaran Ke-4','09:15','[\"Senin\", \"Selasa\", \"Rabu\", \"Kamis\", \"Jumat\"]','chime',NULL,NULL,NULL,95,10,'Pergantian mata pelajaran jam ke-4','Saatnya pergantian jam pelajaran ke-4.',1,5,'2026-11-10 11:51:58','2026-11-10 11:51:58'),(6,'Bel Istirahat Pertama & Murottal Santai','10:00','[\"Senin\", \"Selasa\", \"Rabu\", \"Kamis\", \"Jumat\"]','murottal',NULL,56,'Al-Waqi\'ah',80,1200,'Waktu istirahat pertama 20 menit disertai murottal Al-Qur\'an','Saatnya istirahat pertama. Selamat beristirahat.',1,6,'2026-11-10 11:51:58','2026-11-10 11:51:58'),(7,'Bel Masuk KBM Jam Ke-5 (Selesai Istirahat 1)','10:20','[\"Senin\", \"Selasa\", \"Rabu\", \"Kamis\", \"Jumat\"]','chime',NULL,NULL,NULL,100,15,'Istirahat pertama selesai, kembali masuk ke ruang kelas masing-masing','Wakt