INSERT INTO `spmb_tracks` VALUES (1,'Jalur Zonasi','zonasi',50.00,180,'Jalur penerimaan berdasarkan radius jarak tempat tinggal / domisili calon peserta didik ke sekolah sesuai Kartu Keluarga (KK) yang diterbitkan minimal 1 tahun.','1. Kartu Keluarga (KK) min. 1 tahun\n2. Akta Kelahiran\n3. Ijazah/SKL SMP/MTs\n4. Titik koordinat tempat tinggal',0,1,1,'2026-11-05 13:42:39','2026-11-05 13:42:39'),(2,'Jalur Tes Kemampuan Akademik (TKA)','tka',20.00,72,'Jalur seleksi objektif melalui asesmen terstandar TKA (Literasi Bahasa & Penalaran, Numerasi Matematika, dan Literasi Sains) yang diselenggarakan oleh panitia sekolah.','1. SKL/Surat Keterangan Siswa Kelas 9\n2. Rapor SMP semester 1-5\n3. Wajib mengikuti Asesmen TKA Berbasis Komputer di Lab SMAN 1 Lengkong',1,1,2,'2026-11-05 13:42:39','2026-11-05 13:42:39'),(3,'Jalur Afirmasi KETM & Disabilitas','afirmasi',15.00,54,'Jalur diperuntukkan bagi calon peserta didik dari keluarga ekonomi tidak mampu (KETM) terdaftar DTKS/P3KE dan penyandang disabilitas.','1. Kartu KIP / PKH / KKS terdaftar DTKS\n2. Kartu Keluarga & Akta Kelahiran\n3. Surat Pernyataan Tanggung Jawab Mutlak (SPTJM) Orang Tua',0,1,3,'2026-11-05 13:42:39','2026-11-05 13:42:39'),(4,'Jalur Prestasi Nilai Rapor & Kejuaraan','prestasi',10.00,36,'Jalur seleksi berbasis nilai rata-rata rapor semester 1-5 dan/atau piagam sertifikat kejuaraan akademik, sains, seni budaya, dan olahraga min. tingkat kabupaten/kota.','1. Buku Rapor SMP/MTs Semester 1 s.d. 5\n2. Sertifikat/Piagam Kejuaraan Asli (OSN, O2SN, FLS2N, dll.) jika ada',0,1,4,'2026-11-05 13:42:39','2026-11-05 13:42:39'),(5,'Jalur Perpindahan Tugas Orang Tua & Anak Guru','mutasi',5.00,18,'Jalur bagi anak dari orang tua yang berpindah tugas kedinasan (instansi pemerintah/BUMN/TNI/Polri) atau putra-putri pendidik dan tenaga kependidikan SMAN 1 Lengkong.','1. SK Penugasan Mutasi dari Instansi/Lembaga berwenang\n2. Surat Keterangan Domisili baru dari instansi\n3. SK Mengajar bagi Anak Guru/Tendik',0,1,5,'2026-11-05 13:42:39','2026-11-05 13:42:39');
