INSERT INTO `violation_categories` VALUES (1,'P1','Kehadiran','Pelanggaran terkait kedatangan, presensi, absensi tanpa keterangan, dan bolos sekolah.',1,'2026-09-20 16:23:40','2026-09-20 16:23:40'),(2,'P2','Sikap dan Perilaku','Pelanggaran etika sopan santun terhadap bapak/ibu guru, staf, maupun sesama siswa.',1,'2026-09-20 16:23:40','2026-09-20 16:23:40'),(3,'P3','Seragam','Pelanggaran ketentuan penggunaan pakaian seragam sekolah, kelengkapan atribut, dan sepatu.',1,'2026-09-20 16:23:40','2026-09-20 16:23:40'),(4,'P4','Kerapian dan Penampilan','Pelanggaran standar kerapian rambut putra, make-up berlebih putri, perhiasan, dan tato.',1,'2026-09-20 16:23:40','2026-09-20 16:23:40'),(5,'P5','Kedisiplinan','Penyalahgunaan gawai/HP saat KBM, merokok, vape, bermain game, dan membawa barang terlarang.',1,'2026-09-20 16:23:40','2026-09-20 16:23:40'),(6,'P6','Pelanggaran Berat','Perkelahian, narkoba, miras, asusila, pencurian, bullying, dan tindakan melawan hukum.',1,'2026-09-20 16:23:40','2026-09-20 16:23:40');
